ALTER TABLE "rpg_expeditions" DROP CONSTRAINT "rpg_expeditions_settled_state";--> statement-breakpoint
ALTER TABLE "rpg_expeditions" ADD COLUMN "terminal_report" jsonb;--> statement-breakpoint
ALTER TABLE "rpg_expeditions" ADD CONSTRAINT "rpg_expeditions_settled_state" CHECK (("rpg_expeditions"."status" = 'running' AND "rpg_expeditions"."settled_at" IS NULL AND "rpg_expeditions"."settled_reason" IS NULL AND "rpg_expeditions"."settled_cutoff" IS NULL AND "rpg_expeditions"."outcome" IS NULL AND "rpg_expeditions"."terminal_report" IS NULL) OR ("rpg_expeditions"."status" = 'cancelled' AND "rpg_expeditions"."settled_at" IS NOT NULL AND (("rpg_expeditions"."settled_reason" = 'cancelled' AND "rpg_expeditions"."settled_cutoff" IS NOT NULL) OR ("rpg_expeditions"."settled_reason" = 'version_unavailable' AND "rpg_expeditions"."settled_cutoff" IS NULL)) AND "rpg_expeditions"."outcome" IS NULL) OR ("rpg_expeditions"."status" = 'completed' AND "rpg_expeditions"."settled_at" IS NOT NULL AND "rpg_expeditions"."settled_reason" = 'completed' AND "rpg_expeditions"."settled_cutoff" IS NOT NULL AND "rpg_expeditions"."outcome" IS NOT NULL));